      "angle": "Turn the research into a human-readable science story about frontier science, research infrastructure and scientific discovery, avoiding claims beyond the published evidence. For this item, test the claim behind “新疆分院分党组召开理论学习中心组（扩大）专题学习会” against primary-source evidence.",
      "status": "confirmed_today",
      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 党建与科学文化 > 工作动态 6月29日，中国科学院新疆分院分党组召开理论学习中心组（扩大）专题学习会暨树立和践行正确政绩观学习教育第四期读书班。 会议提出，习近平党建思想内涵丰富、体系严密，是加强新时代党的建设的根本遵循，为我们更好履行国家战略科技力量主力军职责使命、加快抢占科技制高点提供了重要指导、指明了前进方向。 会议强调，要增强理论自觉、行动自觉，通过“三会一课”、主题党日、宣讲培训等，深入学习领会习近平党建思想的科学内涵、理论品格、实践基础和理论渊源，深刻领会蕴含其中的坚定理想信念、高度历史主动、鲜明问题导向、强烈使命担当、深厚为民情怀、科学思想方法，整体把握其核心要义、精神实质、实践要求，深切体悟蕴含其中的真理力量和人格力量，更加深刻领悟“两个确立”的决定性意义，以实际行动坚决做到“两个维护”，持之以恒推进全面从严治党，为实现高水平科技自立自强提供坚强政治保障。 会议还集中学习了《习近平关于树立和践行正确政绩观论述摘编》第七部分、《习近平总书记地方工作期间坚持正确政绩观生动实践》部分内容、树立和践行正确政绩观学习教育反面典型案例、新疆维吾尔自治区警示教育会精神等。",
      "relatedTitles": [
        "新疆分院分党组召开理论学习中心组（扩大）专题学习会"
      ],
